-- Saath MVP — app layer. Runs after 20260930000001_schema.sql (generated by Prisma).
-- Everything the client needs runs here: RLS, RPCs, triggers and the scheduled tick.
-- No separate API server: the Expo app talks to Supabase directly.

-- ═════════════════════════ Constraints & defaults ═════════════════════════

ALTER TABLE "Event"
  ADD CONSTRAINT event_capacity CHECK ("minAttendees" >= 4 AND "maxAttendees" <= 8 AND "minAttendees" <= "maxAttendees"),
  ADD CONSTRAINT event_booked CHECK ("bookedCount" >= 0 AND "bookedCount" <= "maxAttendees"),
  ADD CONSTRAINT event_time CHECK ("endsAt" > "startsAt"),
  ADD CONSTRAINT event_money CHECK ("costMinor" >= 0 AND "platformFeeMinor" >= 0);
ALTER TABLE "EventFeedback"
  ADD CONSTRAINT feedback_ratings CHECK ("hostRating" BETWEEN 1 AND 5 AND "venueSafetyRating" BETWEEN 1 AND 5);
ALTER TABLE "Match" ADD CONSTRAINT match_pair_order CHECK ("userAId" < "userBId");
ALTER TABLE "PostEventInteraction" ADD CONSTRAINT interaction_not_self CHECK ("fromUserId" <> "toUserId");
ALTER TABLE "UserBlock" ADD CONSTRAINT block_not_self CHECK ("blockerId" <> "blockedId");
ALTER TABLE "ProfilePhoto" ADD CONSTRAINT photo_position CHECK ("position" BETWEEN 0 AND 5);
ALTER TABLE "SafetyReport" ALTER COLUMN severity SET DEFAULT 'MEDIUM';

-- Prisma's @updatedAt is client-side; direct Supabase writes need a trigger.
CREATE OR REPLACE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW."updatedAt" := now(); RETURN NEW; END $$;

DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['User','Profile','Event','EventBooking','SafetyReport'] LOOP
    EXECUTE format('CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at()', t);
  END LOOP;
END $$;

-- ═════════════════════════ Config ═════════════════════════

-- Platform fee shown in the price breakdown. Change here, nowhere else.
CREATE OR REPLACE FUNCTION public.saath_platform_fee(p_cost_minor int) RETURNS int
LANGUAGE sql IMMUTABLE AS $$ SELECT GREATEST(round(p_cost_minor * 0.10)::int, 0) $$;

-- ═════════════════════════ Helpers (used by RLS) ═════════════════════════

CREATE OR REPLACE FUNCTION public.is_blocked_pair(a uuid, b uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM "UserBlock"
    WHERE ("blockerId" = a AND "blockedId" = b) OR ("blockerId" = b AND "blockedId" = a));
$$;

-- Active, not blocked with the caller (or the caller themself).
CREATE OR REPLACE FUNCTION public.is_visible_user(p_user uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT p_user = auth.uid() OR (
    EXISTS (SELECT 1 FROM "User" WHERE id = p_user AND status = 'ACTIVE')
    AND NOT public.is_blocked_pair(auth.uid(), p_user));
$$;

CREATE OR REPLACE FUNCTION public.my_host_id() RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT id FROM "Host" WHERE "userId" = auth.uid();
$$;

CREATE OR REPLACE FUNCTION public.is_event_host(p_event uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM "Event" e JOIN "Host" h ON h.id = e."hostId"
    WHERE e.id = p_event AND h."userId" = auth.uid());
$$;

-- Host or confirmed attendee, while the logistics channel still exists.
CREATE OR REPLACE FUNCTION public.is_event_member(p_event uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM "Event" WHERE id = p_event AND "channelPurgedAt" IS NULL)
    AND (public.is_event_host(p_event) OR EXISTS (
      SELECT 1 FROM "EventBooking" WHERE "eventId" = p_event AND "userId" = auth.uid() AND status = 'CONFIRMED'));
$$;

CREATE OR REPLACE FUNCTION public.is_match_member(p_match uuid, p_active_only boolean DEFAULT false) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM "Match" WHERE id = p_match
    AND auth.uid() IN ("userAId", "userBId")
    AND (NOT p_active_only OR status = 'ACTIVE'));
$$;

-- Internal: queue a push notification (drained by the send-push Edge Function).
CREATE OR REPLACE FUNCTION public.enqueue_notification(p_user uuid, p_title text, p_body text, p_data jsonb DEFAULT NULL)
RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  INSERT INTO "Notification"("userId", title, body, data) VALUES (p_user, left(p_title, 80), left(p_body, 200), p_data);
$$;

-- ═════════════════════════ Auth → User row ═════════════════════════

CREATE OR REPLACE FUNCTION public.handle_new_auth_user() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO "User"(id, email) VALUES (NEW.id, NEW.email) ON CONFLICT DO NOTHING;
  RETURN NEW;
END $$;

CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_auth_user();

-- ═════════════════════════ Privileges & RLS ═════════════════════════

REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated;

GRANT SELECT ON "User" TO authenticated;
GRANT UPDATE ("expoPushToken", "lastActiveAt") ON "User" TO authenticated;
GRANT SELECT, INSERT, DELETE ON "UserIntent", "UserCatchment" TO authenticated;
GRANT SELECT ON "Profile", "CatchmentArea", "EventBooking", "PostEventInteraction",
  "EventFeedback", "Match", "Notification" TO authenticated;
GRANT UPDATE ("displayName", bio, interests, languages, "budgetMinMinor", "budgetMaxMinor",
  "accessibilityNeeds", dietary, alcohol) ON "Profile" TO authenticated;
GRANT SELECT, DELETE ON "ProfilePhoto" TO authenticated;
GRANT INSERT ("profileId", "storageKey", position) ON "ProfilePhoto" TO authenticated;
GRANT SELECT (id, "catchmentId", name, "publicAreaLabel", accessibility, "isVerified") ON "Venue" TO authenticated;
GRANT SELECT (id, "userId", status, bio, "ratingSum", "ratingCount", "approvedAt", "createdAt") ON "Host" TO authenticated;
GRANT INSERT ("userId", bio), UPDATE (bio) ON "Host" TO authenticated;
GRANT SELECT (id, "hostId", "venueId", "catchmentId", title, description, "coverImageKey", format, tags,
  languages, "dietaryOptions", "alcoholPolicy", "startsAt", "endsAt", "minAttendees", "maxAttendees",
  "bookedCount", "costMinor", "platformFeeMinor", currency, status, "cancelledReason", "matchingStatus",
  "matchingOpensAt", "matchingClosesAt", "createdAt") ON "Event" TO authenticated;
GRANT SELECT ON "Message", "EventChannelMessage" TO authenticated;
GRANT INSERT ("matchId", "senderId", "clientId", body), UPDATE ("readAt") ON "Message" TO authenticated;
GRANT INSERT ("eventId", "senderId", kind, body) ON "EventChannelMessage" TO authenticated;
GRANT SELECT (id, "subjectUserId", "eventId", "matchId", category, status, "isEmergency", "createdAt") ON "SafetyReport" TO authenticated;
GRANT INSERT ("reporterId", "subjectUserId", "eventId", "matchId", category, description, "isEmergency") ON "SafetyReport" TO authenticated;
GRANT SELECT, INSERT ("blockerId", "blockedId", reason), DELETE ON "UserBlock" TO authenticated;

DO $$ DECLARE t text; BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  END LOOP;
END $$;

CREATE POLICY own_row ON "User" FOR ALL TO authenticated
  USING (id = (SELECT auth.uid())) WITH CHECK (id = (SELECT auth.uid()));
CREATE POLICY own_rows ON "UserIntent" FOR ALL TO authenticated
  USING ("userId" = (SELECT auth.uid())) WITH CHECK ("userId" = (SELECT auth.uid()));
CREATE POLICY own_rows ON "UserCatchment" FOR ALL TO authenticated
  USING ("userId" = (SELECT auth.uid())) WITH CHECK ("userId" = (SELECT auth.uid()));

CREATE POLICY read_visible ON "Profile" FOR SELECT TO authenticated USING (public.is_visible_user("userId"));
CREATE POLICY update_own ON "Profile" FOR UPDATE TO authenticated
  USING ("userId" = (SELECT auth.uid())) WITH CHECK ("userId" = (SELECT auth.uid()));

CREATE POLICY read_visible ON "ProfilePhoto" FOR SELECT TO authenticated
  USING ("profileId" = (SELECT auth.uid()) OR ("moderationStatus" = 'APPROVED' AND public.is_visible_user("profileId")));
CREATE POLICY insert_own ON "ProfilePhoto" FOR INSERT TO authenticated WITH CHECK ("profileId" = (SELECT auth.uid()));
CREATE POLICY delete_own ON "ProfilePhoto" FOR DELETE TO authenticated USING ("profileId" = (SELECT auth.uid()));

CREATE POLICY read_all ON "CatchmentArea" FOR SELECT TO authenticated USING ("isActive");
CREATE POLICY read_all ON "Venue" FOR SELECT TO authenticated USING (true);

CREATE POLICY read_host ON "Host" FOR SELECT TO authenticated
  USING (status = 'APPROVED' OR "userId" = (SELECT auth.uid()));
CREATE POLICY apply_self ON "Host" FOR INSERT TO authenticated WITH CHECK ("userId" = (SELECT auth.uid()));
CREATE POLICY update_self ON "Host" FOR UPDATE TO authenticated USING ("userId" = (SELECT auth.uid()));

CREATE POLICY read_event ON "Event" FOR SELECT TO authenticated
  USING (status <> 'DRAFT' OR "hostId" = public.my_host_id());

CREATE POLICY read_booking ON "EventBooking" FOR SELECT TO authenticated
  USING ("userId" = (SELECT auth.uid()) OR public.is_event_host("eventId"));

CREATE POLICY read_own ON "PostEventInteraction" FOR SELECT TO authenticated USING ("fromUserId" = (SELECT auth.uid()));
CREATE POLICY read_own ON "EventFeedback" FOR SELECT TO authenticated USING ("userId" = (SELECT auth.uid()));
CREATE POLICY read_member ON "Match" FOR SELECT TO authenticated USING ((SELECT auth.uid()) IN ("userAId", "userBId"));

CREATE POLICY read_member ON "Message" FOR SELECT TO authenticated USING (public.is_match_member("matchId"));
CREATE POLICY send_active ON "Message" FOR INSERT TO authenticated
  WITH CHECK ("senderId" = (SELECT auth.uid()) AND public.is_match_member("matchId", true));
CREATE POLICY mark_read ON "Message" FOR UPDATE TO authenticated
  USING (public.is_match_member("matchId") AND "senderId" <> (SELECT auth.uid()));

CREATE POLICY read_member ON "EventChannelMessage" FOR SELECT TO authenticated USING (public.is_event_member("eventId"));
CREATE POLICY send_member ON "EventChannelMessage" FOR INSERT TO authenticated
  WITH CHECK ("senderId" = (SELECT auth.uid()) AND public.is_event_member("eventId")
    AND (kind = 'CHAT' OR (kind = 'ANNOUNCEMENT' AND public.is_event_host("eventId"))));

CREATE POLICY read_own ON "SafetyReport" FOR SELECT TO authenticated USING ("reporterId" = (SELECT auth.uid()));
CREATE POLICY file_own ON "SafetyReport" FOR INSERT TO authenticated WITH CHECK ("reporterId" = (SELECT auth.uid()));

CREATE POLICY own_rows ON "UserBlock" FOR ALL TO authenticated
  USING ("blockerId" = (SELECT auth.uid())) WITH CHECK ("blockerId" = (SELECT auth.uid()));

CREATE POLICY read_own ON "Notification" FOR SELECT TO authenticated USING ("userId" = (SELECT auth.uid()));

-- ═════════════════════════ Triggers ═════════════════════════

-- Blocking ends any match between the pair.
CREATE OR REPLACE FUNCTION public.on_user_block() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  UPDATE "Match" SET status = 'BLOCKED', "endedById" = NEW."blockerId", "endedAt" = now()
  WHERE "userAId" = LEAST(NEW."blockerId", NEW."blockedId")
    AND "userBId" = GREATEST(NEW."blockerId", NEW."blockedId") AND status = 'ACTIVE';
  RETURN NEW;
END $$;
CREATE TRIGGER on_user_block AFTER INSERT ON "UserBlock" FOR EACH ROW EXECUTE FUNCTION public.on_user_block();

-- New 1:1 message: bump the thread and notify the other person.
CREATE OR REPLACE FUNCTION public.on_message() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_other uuid; v_name text;
BEGIN
  UPDATE "Match" SET "lastMessageAt" = NEW."createdAt" WHERE id = NEW."matchId"
  RETURNING CASE WHEN "userAId" = NEW."senderId" THEN "userBId" ELSE "userAId" END INTO v_other;
  SELECT "displayName" INTO v_name FROM "Profile" WHERE "userId" = NEW."senderId";
  PERFORM public.enqueue_notification(v_other, coalesce(v_name, 'New message'), left(NEW.body, 120),
    jsonb_build_object('kind', 'message', 'matchId', NEW."matchId"));
  RETURN NEW;
END $$;
CREATE TRIGGER on_message AFTER INSERT ON "Message" FOR EACH ROW EXECUTE FUNCTION public.on_message();

-- Reports: severity is decided server-side; urgent ones page every moderator.
CREATE OR REPLACE FUNCTION public.on_safety_report() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  NEW.severity := CASE
    WHEN NEW."isEmergency" OR NEW.category IN ('SAFETY_THREAT', 'SEXUAL_MISCONDUCT', 'UNDERAGE') THEN 'CRITICAL'
    WHEN NEW.category IN ('HARASSMENT', 'HOST_MISCONDUCT', 'VENUE_UNSAFE') THEN 'HIGH'
    WHEN NEW.category IN ('FAKE_PROFILE', 'INAPPROPRIATE_CONTENT') THEN 'MEDIUM'
    ELSE 'LOW' END::"ReportSeverity";
  IF NEW.severity = 'CRITICAL' THEN
    INSERT INTO "Notification"("userId", title, body, data)
    SELECT id, 'URGENT safety report', left(NEW.category::text || ': ' || NEW.description, 200),
           jsonb_build_object('kind', 'report', 'reportId', NEW.id)
    FROM "User" WHERE role IN ('MODERATOR', 'ADMIN');
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER on_safety_report BEFORE INSERT ON "SafetyReport" FOR EACH ROW EXECUTE FUNCTION public.on_safety_report();

-- ═════════════════════════ Onboarding & verification ═════════════════════════

CREATE OR REPLACE FUNCTION public.complete_onboarding(
  p_date_of_birth date,
  p_display_name text,
  p_intents "IntentType"[],
  p_catchment_ids uuid[],
  p_gender "Gender" DEFAULT NULL,
  p_dating_preferences "Gender"[] DEFAULT '{}',
  p_bio text DEFAULT NULL,
  p_interests text[] DEFAULT '{}',
  p_languages text[] DEFAULT '{}',
  p_budget_max_minor int DEFAULT NULL,
  p_accessibility_needs text[] DEFAULT '{}',
  p_dietary "DietaryPreference"[] DEFAULT '{}',
  p_alcohol "AlcoholPreference" DEFAULT NULL
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_dob date;
  v_age int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT "dateOfBirth" INTO v_dob FROM "User" WHERE id = v_uid;
  IF v_dob IS NOT NULL AND v_dob <> p_date_of_birth THEN RAISE EXCEPTION 'dob_locked'; END IF;
  v_age := date_part('year', age(current_date, p_date_of_birth));
  IF p_date_of_birth IS NULL OR v_age < 21 OR v_age > 35 THEN RAISE EXCEPTION 'age_out_of_range'; END IF;
  IF length(trim(coalesce(p_display_name, ''))) NOT BETWEEN 1 AND 40 THEN RAISE EXCEPTION 'invalid_name'; END IF;
  IF coalesce(cardinality(p_intents), 0) = 0 THEN RAISE EXCEPTION 'intent_required'; END IF;
  IF coalesce(cardinality(p_catchment_ids), 0) NOT BETWEEN 1 AND 3
     OR (SELECT count(*) FROM "CatchmentArea" WHERE id = ANY(p_catchment_ids) AND "isActive") <> cardinality(p_catchment_ids)
  THEN RAISE EXCEPTION 'invalid_catchments'; END IF;

  UPDATE "User" SET "dateOfBirth" = p_date_of_birth, gender = p_gender,
    "datingPreferences" = coalesce(p_dating_preferences, '{}'),
    status = CASE WHEN status = 'ONBOARDING' THEN 'ACTIVE'::"UserStatus" ELSE status END
  WHERE id = v_uid;

  INSERT INTO "Profile"("userId", "displayName", bio, interests, languages, "budgetMaxMinor",
                        "accessibilityNeeds", dietary, alcohol)
  VALUES (v_uid, trim(p_display_name), nullif(trim(p_bio), ''), p_interests, p_languages, p_budget_max_minor,
          p_accessibility_needs, p_dietary, p_alcohol)
  ON CONFLICT ("userId") DO UPDATE SET "displayName" = EXCLUDED."displayName", bio = EXCLUDED.bio,
    interests = EXCLUDED.interests, languages = EXCLUDED.languages, "budgetMaxMinor" = EXCLUDED."budgetMaxMinor",
    "accessibilityNeeds" = EXCLUDED."accessibilityNeeds", dietary = EXCLUDED.dietary, alcohol = EXCLUDED.alcohol,
    "updatedAt" = now();

  DELETE FROM "UserIntent" WHERE "userId" = v_uid;
  INSERT INTO "UserIntent"("userId", intent) SELECT DISTINCT v_uid, i FROM unnest(p_intents) i;

  DELETE FROM "UserCatchment" WHERE "userId" = v_uid;
  INSERT INTO "UserCatchment"("userId", "catchmentId", "isPrimary")
  SELECT DISTINCT v_uid, c, c = p_catchment_ids[1] FROM unnest(p_catchment_ids) c;
END $$;

-- Free selfie verification: user photographs themself doing a random gesture,
-- a moderator compares it with their profile photos in the Supabase dashboard.
CREATE OR REPLACE FUNCTION public.start_verification() RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_gesture text := (ARRAY['Peace sign with your left hand', 'Thumbs up next to your chin',
  'Touch your right ear', 'Three fingers raised', 'Hand flat on top of your head'])[1 + floor(random() * 5)::int];
BEGIN
  UPDATE "User" SET "verificationGesture" = v_gesture WHERE id = auth.uid() AND "verificationStatus" <> 'APPROVED';
  RETURN v_gesture;
END $$;

CREATE OR REPLACE FUNCTION public.submit_verification(p_selfie_key text, p_id_key text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF p_selfie_key NOT LIKE auth.uid()::text || '/%' THEN RAISE EXCEPTION 'invalid_key'; END IF;
  IF p_id_key NOT LIKE auth.uid()::text || '/%' THEN RAISE EXCEPTION 'invalid_key'; END IF;
  UPDATE "User" SET "verificationSelfieKey" = p_selfie_key, "verificationIdKey" = p_id_key,
    "verificationStatus" = 'PENDING'
  WHERE id = auth.uid() AND "verificationGesture" IS NOT NULL AND "verificationStatus" <> 'APPROVED';
  IF NOT FOUND THEN RAISE EXCEPTION 'start_verification_first'; END IF;
END $$;

-- Called by a moderator from the SQL editor: SELECT review_verification('<user id>', true);
CREATE OR REPLACE FUNCTION public.review_verification(p_user uuid, p_approved boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_selfie text; v_id text;
BEGIN
  SELECT "verificationSelfieKey", "verificationIdKey" INTO v_selfie, v_id FROM "User" WHERE id = p_user;
  UPDATE "User" SET "verificationStatus" = CASE WHEN p_approved THEN 'APPROVED' ELSE 'REJECTED' END::"VerificationStatus",
    "verifiedAt" = CASE WHEN p_approved THEN now() END, "verificationGesture" = NULL,
    "verificationSelfieKey" = NULL, "verificationIdKey" = NULL
  WHERE id = p_user;
  DELETE FROM storage.objects WHERE bucket_id = 'verification' AND name IN (v_selfie, v_id);
  PERFORM public.enqueue_notification(p_user,
    CASE WHEN p_approved THEN 'You are verified' ELSE 'Verification needs another try' END,
    CASE WHEN p_approved THEN 'You can now book plans.' ELSE 'Your selfie did not match. Please try again from your profile.' END,
    jsonb_build_object('kind', 'verification'));
END $$;

-- ═════════════════════════ Discovery ═════════════════════════

CREATE OR REPLACE FUNCTION public.discover_events(
  p_catchment_id uuid DEFAULT NULL,
  p_from timestamptz DEFAULT NULL,
  p_to timestamptz DEFAULT NULL,
  p_max_price_minor int DEFAULT NULL,
  p_format "EventFormat" DEFAULT NULL,
  p_language text DEFAULT NULL,
  p_dietary "DietaryPreference" DEFAULT NULL,
  p_alcohol "AlcoholPolicy" DEFAULT NULL
) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce(jsonb_agg(row ORDER BY row->>'startsAt'), '[]'::jsonb) FROM (
    SELECT jsonb_build_object(
      'id', e.id, 'title', e.title, 'format', e.format, 'tags', e.tags, 'languages', e.languages,
      'dietaryOptions', e."dietaryOptions", 'alcoholPolicy', e."alcoholPolicy",
      'startsAt', e."startsAt", 'endsAt', e."endsAt", 'maxAttendees', e."maxAttendees",
      'bookedCount', e."bookedCount", 'costMinor', e."costMinor", 'platformFeeMinor', e."platformFeeMinor",
      'currency', e.currency, 'coverImageKey', e."coverImageKey", 'catchmentName', c.name,
      'areaLabel', v."publicAreaLabel", 'hostName', hp."displayName",
      'myBookingStatus', mb.status) AS row
    FROM "Event" e
    JOIN "Venue" v ON v.id = e."venueId"
    JOIN "CatchmentArea" c ON c.id = e."catchmentId"
    JOIN "Host" h ON h.id = e."hostId"
    LEFT JOIN "Profile" hp ON hp."userId" = h."userId"
    LEFT JOIN "EventBooking" mb ON mb."eventId" = e.id AND mb."userId" = auth.uid()
    WHERE e.status = 'PUBLISHED'
      AND e."startsAt" BETWEEN coalesce(p_from, now()) AND coalesce(p_to, now() + interval '30 days')
      AND CASE WHEN p_catchment_id IS NULL
               THEN e."catchmentId" IN (SELECT "catchmentId" FROM "UserCatchment" WHERE "userId" = auth.uid())
               ELSE e."catchmentId" = p_catchment_id END
      AND (p_max_price_minor IS NULL OR e."costMinor" + e."platformFeeMinor" <= p_max_price_minor)
      AND (p_format IS NULL OR e.format = p_format)
      AND (p_language IS NULL OR p_language = ANY(e.languages))
      AND (p_dietary IS NULL OR p_dietary = ANY(e."dietaryOptions"))
      AND (p_alcohol IS NULL OR e."alcoholPolicy" = p_alcohol)
      AND NOT public.is_blocked_pair(auth.uid(), h."userId")
      AND NOT EXISTS (SELECT 1 FROM "EventBooking" b WHERE b."eventId" = e.id
                        AND b.status IN ('HELD', 'CONFIRMED', 'WAITLISTED')
                        AND public.is_blocked_pair(auth.uid(), b."userId"))
    ORDER BY e."startsAt"
    LIMIT 100
  ) s;
$$;

-- Full event view. Address and check-in code are only included for people allowed to see them.
CREATE OR REPLACE FUNCTION public.event_detail(p_event_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE v_uid uuid := auth.uid(); v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', e.id, 'title', e.title, 'description', e.description, 'format', e.format, 'tags', e.tags,
    'languages', e.languages, 'dietaryOptions', e."dietaryOptions", 'alcoholPolicy', e."alcoholPolicy",
    'startsAt', e."startsAt", 'endsAt', e."endsAt", 'minAttendees', e."minAttendees",
    'maxAttendees', e."maxAttendees", 'bookedCount', e."bookedCount", 'costMinor', e."costMinor",
    'platformFeeMinor', e."platformFeeMinor", 'currency', e.currency, 'status', e.status,
    'cancelledReason', e."cancelledReason", 'coverImageKey', e."coverImageKey",
    'matchingStatus', e."matchingStatus", 'matchingOpensAt', e."matchingOpensAt",
    'matchingClosesAt', e."matchingClosesAt", 'catchmentName', c.name, 'areaLabel', v."publicAreaLabel",
    'accessibility', v.accessibility, 'emergencyNumber', c."emergencyNumber",
    'hostUserId', h."userId", 'hostName', hp."displayName", 'hostBio', h.bio,
    'hostRating', CASE WHEN h."ratingCount" > 0 THEN round(h."ratingSum"::numeric / h."ratingCount", 1) END,
    'isHost', h."userId" = v_uid,
    'myBooking', (SELECT jsonb_build_object('status', b.status, 'attendance', b.attendance,
                    'waitlistPosition', b."waitlistPosition")
                  FROM "EventBooking" b WHERE b."eventId" = e.id AND b."userId" = v_uid),
    'address', CASE WHEN h."userId" = v_uid OR EXISTS (SELECT 1 FROM "EventBooking" b
                 WHERE b."eventId" = e.id AND b."userId" = v_uid AND b.status = 'CONFIRMED')
               THEN v."addressLine" END,
    'checkInCode', CASE WHEN h."userId" = v_uid THEN e."checkInCode" END)
  INTO v
  FROM "Event" e
  JOIN "Venue" v ON v.id = e."venueId"
  JOIN "CatchmentArea" c ON c.id = e."catchmentId"
  JOIN "Host" h ON h.id = e."hostId"
  LEFT JOIN "Profile" hp ON hp."userId" = h."userId"
  WHERE e.id = p_event_id AND (e.status <> 'DRAFT' OR h."userId" = v_uid)
    AND NOT public.is_blocked_pair(v_uid, h."userId");
  RETURN v;
END $$;

-- Upcoming and past plans the caller booked or hosts.
CREATE OR REPLACE FUNCTION public.my_plans() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce(jsonb_agg(row ORDER BY (row->>'startsAt') DESC), '[]'::jsonb) FROM (
    SELECT jsonb_build_object('id', e.id, 'title', e.title, 'startsAt', e."startsAt", 'endsAt', e."endsAt",
      'status', e.status, 'matchingStatus', e."matchingStatus", 'areaLabel', v."publicAreaLabel",
      'isHost', h."userId" = auth.uid(), 'bookingStatus', b.status, 'attendance', b.attendance) AS row
    FROM "Event" e
    JOIN "Venue" v ON v.id = e."venueId"
    JOIN "Host" h ON h.id = e."hostId"
    LEFT JOIN "EventBooking" b ON b."eventId" = e.id AND b."userId" = auth.uid()
    WHERE h."userId" = auth.uid() OR b.status IN ('CONFIRMED', 'WAITLISTED', 'HELD')
    ORDER BY e."startsAt" DESC
    LIMIT 50
  ) s;
$$;

-- Names of the host and confirmed attendees, for members only (group chat, "who's coming").
CREATE OR REPLACE FUNCTION public.event_members(p_event_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.is_event_member(p_event_id) THEN RAISE EXCEPTION 'not_a_member'; END IF;
  RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('userId', m.uid, 'displayName', p."displayName",
            'isHost', m.is_host)), '[]'::jsonb)
    FROM (SELECT h."userId" AS uid, true AS is_host FROM "Event" e JOIN "Host" h ON h.id = e."hostId" WHERE e.id = p_event_id
          UNION
          SELECT b."userId", false FROM "EventBooking" b WHERE b."eventId" = p_event_id AND b.status = 'CONFIRMED') m
    JOIN "Profile" p ON p."userId" = m.uid);
END $$;

-- ═════════════════════════ Booking ═════════════════════════

-- MVP payment model: provider FREE = the price breakdown is shown in-app and paid to the host
-- at the venue. Swap in Razorpay/Stripe later by adding a HELD → CONFIRMED webhook step.
CREATE OR REPLACE FUNCTION public.book_event(p_event_id uuid) RETURNS "BookingStatus"
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_user "User";
  v_event "Event";
  v_host_user uuid;
  v_existing "BookingStatus";
  v_status "BookingStatus";
  v_pos int;
BEGIN
  SELECT * INTO v_user FROM "User" WHERE id = v_uid;
  IF v_user.status IS DISTINCT FROM 'ACTIVE' THEN RAISE EXCEPTION 'account_not_active'; END IF;
  IF v_user."verificationStatus" <> 'APPROVED' THEN RAISE EXCEPTION 'verification_required'; END IF;

  SELECT * INTO v_event FROM "Event" WHERE id = p_event_id FOR UPDATE;
  IF NOT FOUND OR v_event.status <> 'PUBLISHED' OR v_event."startsAt" <= now() THEN
    RAISE EXCEPTION 'event_not_bookable';
  END IF;
  SELECT "userId" INTO v_host_user FROM "Host" WHERE id = v_event."hostId";
  IF v_host_user = v_uid THEN RAISE EXCEPTION 'host_cannot_book'; END IF;
  -- Blocked pairs never share a plan. Same error as "not bookable" so nothing leaks.
  IF public.is_blocked_pair(v_uid, v_host_user) OR EXISTS (
       SELECT 1 FROM "EventBooking" b WHERE b."eventId" = p_event_id
         AND b.status IN ('HELD', 'CONFIRMED', 'WAITLISTED') AND public.is_blocked_pair(v_uid, b."userId"))
  THEN RAISE EXCEPTION 'event_not_bookable'; END IF;

  SELECT status INTO v_existing FROM "EventBooking" WHERE "eventId" = p_event_id AND "userId" = v_uid;
  IF v_existing IN ('HELD', 'CONFIRMED', 'WAITLISTED') THEN RETURN v_existing; END IF;

  IF v_event."bookedCount" < v_event."maxAttendees" THEN
    v_status := 'CONFIRMED';
    UPDATE "Event" SET "bookedCount" = "bookedCount" + 1 WHERE id = p_event_id;
  ELSE
    v_status := 'WAITLISTED';
    SELECT coalesce(max("waitlistPosition"), 0) + 1 INTO v_pos
    FROM "EventBooking" WHERE "eventId" = p_event_id AND status = 'WAITLISTED';
  END IF;

  INSERT INTO "EventBooking"("eventId", "userId", status, "waitlistPosition", "amountMinor",
                             "platformFeeMinor", currency, provider, "idempotencyKey")
  VALUES (p_event_id, v_uid, v_status, v_pos, v_event."costMinor" + v_event."platformFeeMinor",
          v_event."platformFeeMinor", v_event.currency, 'FREE', p_event_id::text || ':' || v_uid::text)
  ON CONFLICT ("eventId", "userId") DO UPDATE SET status = EXCLUDED.status,
    "waitlistPosition" = EXCLUDED."waitlistPosition", "amountMinor" = EXCLUDED."amountMinor",
    "platformFeeMinor" = EXCLUDED."platformFeeMinor", attendance = 'UNKNOWN',
    "cancelledAt" = NULL, "cancellationSource" = NULL;
  RETURN v_status;
END $$;

-- Internal: fill freed seats from the waitlist, in order.
CREATE OR REPLACE FUNCTION public.promote_waitlist(p_event_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_event "Event"; v_next "EventBooking";
BEGIN
  LOOP
    SELECT * INTO v_event FROM "Event" WHERE id = p_event_id FOR UPDATE;
    EXIT WHEN v_event.status <> 'PUBLISHED' OR v_event."bookedCount" >= v_event."maxAttendees";
    SELECT * INTO v_next FROM "EventBooking" WHERE "eventId" = p_event_id AND status = 'WAITLISTED'
      ORDER BY "waitlistPosition" LIMIT 1 FOR UPDATE;
    EXIT WHEN NOT FOUND;
    UPDATE "EventBooking" SET status = 'CONFIRMED', "waitlistPosition" = NULL WHERE id = v_next.id;
    UPDATE "Event" SET "bookedCount" = "bookedCount" + 1 WHERE id = p_event_id;
    PERFORM public.enqueue_notification(v_next."userId", 'You are in: ' || v_event.title,
      'A spot opened up and your seat is confirmed.', jsonb_build_object('kind', 'booking', 'eventId', p_event_id));
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.cancel_booking(p_event_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_event "Event"; v_status "BookingStatus";
BEGIN
  SELECT * INTO v_event FROM "Event" WHERE id = p_event_id FOR UPDATE;
  SELECT status INTO v_status FROM "EventBooking" WHERE "eventId" = p_event_id AND "userId" = auth.uid() FOR UPDATE;
  IF v_status IS NULL OR v_status NOT IN ('HELD', 'CONFIRMED', 'WAITLISTED') THEN RETURN; END IF;
  IF v_event."startsAt" <= now() THEN RAISE EXCEPTION 'too_late_to_cancel'; END IF;
  UPDATE "EventBooking" SET status = 'CANCELLED', "waitlistPosition" = NULL, "cancelledAt" = now(),
    "cancellationSource" = 'USER'
  WHERE "eventId" = p_event_id AND "userId" = auth.uid();
  IF v_status IN ('HELD', 'CONFIRMED') THEN
    UPDATE "Event" SET "bookedCount" = "bookedCount" - 1 WHERE id = p_event_id;
    PERFORM public.promote_waitlist(p_event_id);
  END IF;
END $$;

-- ═════════════════════════ Hosting ═════════════════════════

CREATE OR REPLACE FUNCTION public.host_create_event(
  p_catchment_id uuid,
  p_venue_name text,
  p_area_label text,
  p_address text,
  p_title text,
  p_description text,
  p_format "EventFormat",
  p_starts_at timestamptz,
  p_ends_at timestamptz,
  p_cost_minor int,
  p_max_attendees int DEFAULT 8,
  p_min_attendees int DEFAULT 4,
  p_tags "EventTag"[] DEFAULT '{}',
  p_languages text[] DEFAULT '{}',
  p_dietary_options "DietaryPreference"[] DEFAULT '{}',
  p_alcohol_policy "AlcoholPolicy" DEFAULT 'ALCOHOL_OPTIONAL',
  p_accessibility text[] DEFAULT '{}'
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_host uuid; v_venue uuid; v_event uuid; v_currency text;
BEGIN
  SELECT id INTO v_host FROM "Host" WHERE "userId" = auth.uid() AND status = 'APPROVED';
  IF v_host IS NULL THEN RAISE EXCEPTION 'not_an_approved_host'; END IF;
  SELECT currency INTO v_currency FROM "CatchmentArea" WHERE id = p_catchment_id AND "isActive";
  IF v_currency IS NULL THEN RAISE EXCEPTION 'invalid_catchment'; END IF;
  IF p_starts_at < now() + interval '6 hours' THEN RAISE EXCEPTION 'start_at_least_6h_ahead'; END IF;
  IF p_ends_at <= p_starts_at OR p_ends_at > p_starts_at + interval '12 hours' THEN RAISE EXCEPTION 'invalid_end_time'; END IF;
  IF p_cost_minor < 0 THEN RAISE EXCEPTION 'invalid_cost'; END IF;
  IF length(trim(p_title)) < 3 OR length(trim(p_address)) < 5 OR length(trim(p_area_label)) < 2 THEN
    RAISE EXCEPTION 'missing_details';
  END IF;

  INSERT INTO "Venue"("catchmentId", "createdByHostId", name, "publicAreaLabel", "addressLine", accessibility)
  VALUES (p_catchment_id, v_host, trim(p_venue_name), trim(p_area_label), trim(p_address), p_accessibility)
  RETURNING id INTO v_venue;

  INSERT INTO "Event"("hostId", "venueId", "catchmentId", title, description, format, tags, languages,
    "dietaryOptions", "alcoholPolicy", "startsAt", "endsAt", "minAttendees", "maxAttendees",
    "costMinor", "platformFeeMinor", currency, status)
  VALUES (v_host, v_venue, p_catchment_id, trim(p_title), trim(coalesce(p_description, '')), p_format, p_tags,
    p_languages, p_dietary_options, p_alcohol_policy, p_starts_at, p_ends_at, p_min_attendees, p_max_attendees,
    p_cost_minor, public.saath_platform_fee(p_cost_minor), v_currency, 'PUBLISHED')
  RETURNING id INTO v_event;
  RETURN v_event;
END $$;

-- Internal: cancel an event and everyone's seat, then tell them.
CREATE OR REPLACE FUNCTION public.cancel_event_internal(p_event_id uuid, p_reason text, p_source "CancellationSource")
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_title text;
BEGIN
  UPDATE "Event" SET status = 'CANCELLED', "cancelledReason" = p_reason, "bookedCount" = 0
  WHERE id = p_event_id AND status IN ('DRAFT', 'PUBLISHED') RETURNING title INTO v_title;
  IF NOT FOUND THEN RETURN; END IF;
  WITH c AS (
    UPDATE "EventBooking" SET status = 'CANCELLED', "waitlistPosition" = NULL, "cancelledAt" = now(),
      "cancellationSource" = p_source
    WHERE "eventId" = p_event_id AND status IN ('HELD', 'CONFIRMED', 'WAITLISTED')
    RETURNING "userId")
  INSERT INTO "Notification"("userId", title, body, data)
  SELECT "userId", left('Cancelled: ' || v_title, 80), left(p_reason, 200),
         jsonb_build_object('kind', 'cancelled', 'eventId', p_event_id)
  FROM c;
END $$;

CREATE OR REPLACE FUNCTION public.host_cancel_event(p_event_id uuid, p_reason text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.is_event_host(p_event_id) THEN RAISE EXCEPTION 'not_the_host'; END IF;
  PERFORM public.cancel_event_internal(p_event_id,
    coalesce(nullif(trim(p_reason), ''), 'The host had to cancel this plan.'), 'HOST');
END $$;

CREATE OR REPLACE FUNCTION public.host_roster(p_event_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.is_event_host(p_event_id) THEN RAISE EXCEPTION 'not_the_host'; END IF;
  RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('userId', b."userId", 'displayName', p."displayName",
      'status', b.status, 'attendance', b.attendance, 'waitlistPosition', b."waitlistPosition")
      ORDER BY b.status, b."waitlistPosition", p."displayName"), '[]'::jsonb)
    FROM "EventBooking" b JOIN "Profile" p ON p."userId" = b."userId"
    WHERE b."eventId" = p_event_id AND b.status IN ('CONFIRMED', 'WAITLISTED'));
END $$;

CREATE OR REPLACE FUNCTION public.host_set_attendance(p_event_id uuid, p_user uuid, p_checked_in boolean)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.is_event_host(p_event_id) THEN RAISE EXCEPTION 'not_the_host'; END IF;
  UPDATE "EventBooking" b SET attendance = CASE WHEN p_checked_in THEN 'CHECKED_IN' ELSE 'UNKNOWN' END::"AttendanceStatus",
    "checkedInAt" = CASE WHEN p_checked_in THEN now() END
  FROM "Event" e
  WHERE b."eventId" = e.id AND e.id = p_event_id AND b."userId" = p_user AND b.status = 'CONFIRMED'
    AND e."matchingStatus" = 'NOT_OPEN' AND e.status IN ('PUBLISHED', 'IN_PROGRESS', 'COMPLETED')
    AND now() >= e."startsAt" - interval '30 minutes';
  IF NOT FOUND THEN RAISE EXCEPTION 'attendance_locked'; END IF;
END $$;

-- ═════════════════════════ Check-in ═════════════════════════

-- Attendee types the 4-digit code the host shows at the venue.
CREATE OR REPLACE FUNCTION public.check_in(p_event_id uuid, p_code text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  UPDATE "EventBooking" b SET attendance = 'CHECKED_IN', "checkedInAt" = now()
  FROM "Event" e
  WHERE b."eventId" = e.id AND e.id = p_event_id AND b."userId" = auth.uid() AND b.status = 'CONFIRMED'
    AND e.status IN ('PUBLISHED', 'IN_PROGRESS') AND e."checkInCode" = trim(p_code)
    AND now() BETWEEN e."startsAt" - interval '30 minutes' AND e."endsAt";
  IF NOT FOUND THEN RAISE EXCEPTION 'check_in_failed'; END IF;
END $$;

-- ═════════════════════════ Double-blind matching ═════════════════════════

-- Can p_user date p_other? Needs a DATING intent and p_other's gender inside p_user's preferences
-- (empty preferences = open to everyone).
CREATE OR REPLACE FUNCTION public.dating_ok(p_user uuid, p_other uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((
    SELECT EXISTS (SELECT 1 FROM "UserIntent" WHERE "userId" = p_user AND intent = 'DATING')
       AND (cardinality(u."datingPreferences") = 0 OR o.gender = ANY(u."datingPreferences"))
    FROM "User" u, "User" o WHERE u.id = p_user AND o.id = p_other), false);
$$;

-- The compatibility matrix. Mirrors resolveMatchType() in mobile/src/lib/matching.ts.
--   PASS on either side             → nothing
--   both want dating + both eligible → DATING
--   both accept friendship           → FRIENDSHIP (EITHER counts as both)
--   anything else                    → nothing (a DATING pick is never downgraded)
CREATE OR REPLACE FUNCTION public.resolve_match_type(
  a "InteractionChoice", b "InteractionChoice", a_dating_ok boolean, b_dating_ok boolean
) RETURNS "MatchType" LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE
    WHEN a = 'PASS' OR b = 'PASS' THEN NULL
    WHEN a IN ('DATING', 'EITHER') AND b IN ('DATING', 'EITHER') AND a_dating_ok AND b_dating_ok THEN 'DATING'
    WHEN a IN ('FRIENDSHIP', 'EITHER') AND b IN ('FRIENDSHIP', 'EITHER') THEN 'FRIENDSHIP'
    ELSE NULL
  END::"MatchType";
$$;

CREATE OR REPLACE FUNCTION public.matching_candidates(p_event_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "EventBooking" WHERE "eventId" = p_event_id AND "userId" = v_uid
                 AND attendance = 'CHECKED_IN') THEN
    RAISE EXCEPTION 'not_attended';
  END IF;
  RETURN jsonb_build_object(
    'matchingStatus', (SELECT "matchingStatus" FROM "Event" WHERE id = p_event_id),
    'feedbackDone', EXISTS (SELECT 1 FROM "EventFeedback" WHERE "eventId" = p_event_id AND "userId" = v_uid),
    'candidates', (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'userId', b."userId", 'displayName', p."displayName",
        'photoKey', (SELECT ph."storageKey" FROM "ProfilePhoto" ph WHERE ph."profileId" = b."userId"
                       AND ph."moderationStatus" <> 'REJECTED' ORDER BY ph.position LIMIT 1),
        'myChoice', (SELECT i.choice FROM "PostEventInteraction" i WHERE i."eventId" = p_event_id
                       AND i."fromUserId" = v_uid AND i."toUserId" = b."userId"))
        ORDER BY p."displayName"), '[]'::jsonb)
      FROM "EventBooking" b JOIN "Profile" p ON p."userId" = b."userId"
      WHERE b."eventId" = p_event_id AND b.attendance = 'CHECKED_IN' AND b."userId" <> v_uid
        AND NOT public.is_blocked_pair(v_uid, b."userId")));
END $$;

-- One private submission per attendee: safety feedback + picks. Picks are write-once.
CREATE OR REPLACE FUNCTION public.submit_post_event(
  p_event_id uuid,
  p_choices jsonb,               -- [{"toUserId": "...", "choice": "DATING"}]
  p_host_rating int,
  p_venue_safety_rating int,
  p_felt_safe boolean,
  p_comment text DEFAULT NULL
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_uid uuid := auth.uid(); v_event "Event"; v_rows int;
BEGIN
  SELECT * INTO v_event FROM "Event" WHERE id = p_event_id;
  IF v_event."matchingStatus" IS DISTINCT FROM 'OPEN' THEN RAISE EXCEPTION 'matching_not_open'; END IF;
  IF NOT EXISTS (SELECT 1 FROM "EventBooking" WHERE "eventId" = p_event_id AND "userId" = v_uid
                 AND attendance = 'CHECKED_IN') THEN RAISE EXCEPTION 'not_attended'; END IF;

  INSERT INTO "EventFeedback"("eventId", "userId", "hostRating", "venueSafetyRating", "feltSafe", comment)
  VALUES (p_event_id, v_uid, p_host_rating, p_venue_safety_rating, p_felt_safe, nullif(trim(p_comment), ''))
  ON CONFLICT ("eventId", "userId") DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 1 THEN
    UPDATE "Host" SET "ratingSum" = "ratingSum" + p_host_rating, "ratingCount" = "ratingCount" + 1
    WHERE id = v_event."hostId";
    IF NOT p_felt_safe THEN
      INSERT INTO "SafetyReport"("reporterId", "eventId", category, description)
      VALUES (v_uid, p_event_id, 'VENUE_UNSAFE',
              coalesce(nullif(trim(p_comment), ''), 'Attendee reported not feeling safe (post-event survey).'));
    END IF;
  END IF;

  INSERT INTO "PostEventInteraction"("eventId", "fromUserId", "toUserId", choice)
  SELECT p_event_id, v_uid, x.to_id, x.choice
  FROM (SELECT (e->>'toUserId')::uuid AS to_id, (e->>'choice')::"InteractionChoice" AS choice
        FROM jsonb_array_elements(coalesce(p_choices, '[]'::jsonb)) e) x
  WHERE x.to_id <> v_uid
    AND EXISTS (SELECT 1 FROM "EventBooking" b WHERE b."eventId" = p_event_id AND b."userId" = x.to_id
                AND b.attendance = 'CHECKED_IN')
  ON CONFLICT ("eventId", "fromUserId", "toUserId") DO NOTHING;
END $$;

-- Internal: runs once when the window closes. Everyone who attended gets the same notification,
-- so nobody can infer a non-match from timing or wording.
CREATE OR REPLACE FUNCTION public.compute_matches(p_event_id uuid) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_count int; v_title text;
BEGIN
  SELECT title INTO v_title FROM "Event" WHERE id = p_event_id;
  WITH pairs AS (
    SELECT x."fromUserId" AS a, x."toUserId" AS b,
           public.resolve_match_type(x.choice, y.choice,
             public.dating_ok(x."fromUserId", x."toUserId"), public.dating_ok(x."toUserId", x."fromUserId")) AS mt
    FROM "PostEventInteraction" x
    JOIN "PostEventInteraction" y ON y."eventId" = x."eventId"
      AND y."fromUserId" = x."toUserId" AND y."toUserId" = x."fromUserId"
    WHERE x."eventId" = p_event_id AND x."fromUserId" < x."toUserId"
  ), ins AS (
    INSERT INTO "Match"("eventId", "userAId", "userBId", type)
    SELECT p_event_id, p.a, p.b, p.mt FROM pairs p
    JOIN "User" ua ON ua.id = p.a AND ua.status = 'ACTIVE'
    JOIN "User" ub ON ub.id = p.b AND ub.status = 'ACTIVE'
    WHERE p.mt IS NOT NULL AND NOT public.is_blocked_pair(p.a, p.b)
    ON CONFLICT ("userAId", "userBId") DO NOTHING
    RETURNING id)
  SELECT count(*) INTO v_count FROM ins;

  INSERT INTO "Notification"("userId", title, body, data)
  SELECT b."userId", 'Your results are in',
         left('See if anyone from ' || v_title || ' picked you too.', 200),
         jsonb_build_object('kind', 'matching_closed', 'eventId', p_event_id)
  FROM "EventBooking" b WHERE b."eventId" = p_event_id AND b.attendance = 'CHECKED_IN';
  RETURN v_count;
END $$;

CREATE OR REPLACE FUNCTION public.my_matches() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce(jsonb_agg(row ORDER BY coalesce(row->>'lastMessageAt', row->>'createdAt') DESC), '[]'::jsonb) FROM (
    SELECT jsonb_build_object('id', m.id, 'type', m.type, 'createdAt', m."createdAt",
      'lastMessageAt', m."lastMessageAt", 'eventTitle', e.title, 'otherUserId', o.uid,
      'otherName', p."displayName",
      'otherPhotoKey', (SELECT ph."storageKey" FROM "ProfilePhoto" ph WHERE ph."profileId" = o.uid
                          AND ph."moderationStatus" <> 'REJECTED' ORDER BY ph.position LIMIT 1)) AS row
    FROM "Match" m
    JOIN "Event" e ON e.id = m."eventId"
    CROSS JOIN LATERAL (SELECT CASE WHEN m."userAId" = auth.uid() THEN m."userBId" ELSE m."userAId" END AS uid) o
    LEFT JOIN "Profile" p ON p."userId" = o.uid
    WHERE auth.uid() IN (m."userAId", m."userBId") AND m.status = 'ACTIVE'
  ) s;
$$;

CREATE OR REPLACE FUNCTION public.unmatch(p_match_id uuid) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  UPDATE "Match" SET status = 'UNMATCHED', "endedById" = auth.uid(), "endedAt" = now()
  WHERE id = p_match_id AND auth.uid() IN ("userAId", "userBId") AND status = 'ACTIVE';
$$;

-- ═════════════════════════ Account ═════════════════════════

-- Required by the App Store. Keeps the anonymised User row so bookings/reports stay consistent.
-- The client deletes the user's storage files before calling this.
CREATE OR REPLACE FUNCTION public.delete_my_account() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_uid uuid := auth.uid(); r record;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  FOR r IN SELECT "eventId" FROM "EventBooking" b JOIN "Event" e ON e.id = b."eventId"
           WHERE b."userId" = v_uid AND b.status IN ('HELD', 'CONFIRMED', 'WAITLISTED') AND e."startsAt" > now() LOOP
    PERFORM public.cancel_booking(r."eventId");
  END LOOP;
  FOR r IN SELECT e.id FROM "Event" e JOIN "Host" h ON h.id = e."hostId"
           WHERE h."userId" = v_uid AND e.status IN ('DRAFT', 'PUBLISHED') LOOP
    PERFORM public.cancel_event_internal(r.id, 'The host closed their account.', 'SYSTEM');
  END LOOP;
  UPDATE "Match" SET status = 'UNMATCHED', "endedById" = v_uid, "endedAt" = now()
  WHERE v_uid IN ("userAId", "userBId") AND status = 'ACTIVE';
  DELETE FROM "Profile" WHERE "userId" = v_uid;
  DELETE FROM "UserIntent" WHERE "userId" = v_uid;
  DELETE FROM "UserCatchment" WHERE "userId" = v_uid;
  UPDATE "Host" SET status = 'REVOKED' WHERE "userId" = v_uid;
  UPDATE "User" SET status = 'DELETED', "deletedAt" = now(), email = NULL, "phoneE164" = NULL,
    "expoPushToken" = NULL, gender = NULL, "datingPreferences" = '{}', "verificationSelfieKey" = NULL,
    "verificationGesture" = NULL
  WHERE id = v_uid;
  DELETE FROM auth.users WHERE id = v_uid;
END $$;

-- ═════════════════════════ Scheduled tick (pg_cron, every 5 min) ═════════════════════════

CREATE OR REPLACE FUNCTION public.saath_tick() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE r record;
BEGIN
  -- 1. Auto-cancel plans that are still under minimum 3 hours before start.
  FOR r IN SELECT id FROM "Event" WHERE status = 'PUBLISHED'
           AND "startsAt" <= now() + interval '3 hours' AND "bookedCount" < "minAttendees" LOOP
    PERFORM public.cancel_event_internal(r.id, 'Not enough people joined this time, so the plan is off.', 'SYSTEM');
  END LOOP;

  -- 2. Reminder ~2 hours before start (deduplicated through the outbox).
  INSERT INTO "Notification"("userId", title, body, data)
  SELECT b."userId", left('Starting soon: ' || e.title, 80),
         'Your plan starts in about 2 hours. The address and group chat are in the app.',
         jsonb_build_object('kind', 'reminder', 'eventId', e.id)
  FROM "Event" e JOIN "EventBooking" b ON b."eventId" = e.id AND b.status = 'CONFIRMED'
  WHERE e.status = 'PUBLISHED' AND e."startsAt" BETWEEN now() AND now() + interval '2 hours'
    AND NOT EXISTS (SELECT 1 FROM "Notification" n WHERE n."userId" = b."userId"
                    AND n.data->>'kind' = 'reminder' AND n.data->>'eventId' = e.id::text);

  -- 3. Start: close the waitlist.
  WITH started AS (
    UPDATE "Event" SET status = 'IN_PROGRESS' WHERE status = 'PUBLISHED' AND "startsAt" <= now() RETURNING id)
  UPDATE "EventBooking" b SET status = 'EXPIRED', "waitlistPosition" = NULL
  FROM started s WHERE b."eventId" = s.id AND b.status IN ('WAITLISTED', 'HELD');

  -- 4. End: schedule the private matching window (opens +2h, closes +24h after the end).
  UPDATE "Event" SET status = 'COMPLETED', "matchingOpensAt" = "endsAt" + interval '2 hours',
    "matchingClosesAt" = "endsAt" + interval '24 hours'
  WHERE status = 'IN_PROGRESS' AND "endsAt" <= now();

  -- 5. Open matching; anyone not checked in by now is a no-show.
  WITH opened AS (
    UPDATE "Event" SET "matchingStatus" = 'OPEN'
    WHERE status = 'COMPLETED' AND "matchingStatus" = 'NOT_OPEN' AND "matchingOpensAt" <= now()
    RETURNING id, title),
  noshow AS (
    UPDATE "EventBooking" b SET attendance = 'NO_SHOW' FROM opened o
    WHERE b."eventId" = o.id AND b.status = 'CONFIRMED' AND b.attendance = 'UNKNOWN' RETURNING b.id)
  INSERT INTO "Notification"("userId", title, body, data)
  SELECT b."userId", left('How was ' || o.title || '?', 80),
         'Privately pick who you would like to see again. Nobody sees your picks.',
         jsonb_build_object('kind', 'matching_open', 'eventId', o.id)
  FROM opened o JOIN "EventBooking" b ON b."eventId" = o.id AND b.attendance = 'CHECKED_IN';

  -- 6. Close matching and reveal mutual matches all at once.
  FOR r IN SELECT id FROM "Event" WHERE "matchingStatus" = 'OPEN' AND "matchingClosesAt" <= now() FOR UPDATE LOOP
    PERFORM public.compute_matches(r.id);
    UPDATE "Event" SET "matchingStatus" = 'CLOSED' WHERE id = r.id;
  END LOOP;

  -- 7. Purge logistics chats 48h after the plan, and old sent notifications.
  WITH purged AS (
    UPDATE "Event" SET "channelPurgedAt" = now()
    WHERE status IN ('COMPLETED', 'CANCELLED') AND "channelPurgedAt" IS NULL AND "endsAt" < now() - interval '48 hours'
    RETURNING id)
  DELETE FROM "EventChannelMessage" m USING purged p WHERE m."eventId" = p.id;
  DELETE FROM "Notification" WHERE "sentAt" < now() - interval '30 days';
END $$;

-- ═════════════════════════ Function privileges ═════════════════════════

REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC, anon, authenticated;

-- RLS helpers (evaluated as the caller)
GRANT EXECUTE ON FUNCTION public.is_blocked_pair, public.is_visible_user, public.my_host_id,
  public.is_event_host, public.is_event_member, public.is_match_member TO authenticated;
-- Client RPCs
GRANT EXECUTE ON FUNCTION public.complete_onboarding, public.start_verification, public.submit_verification,
  public.discover_events, public.event_detail, public.my_plans, public.event_members, public.book_event,
  public.cancel_booking, public.host_create_event, public.host_cancel_event, public.host_roster,
  public.host_set_attendance, public.check_in, public.matching_candidates, public.submit_post_event,
  public.my_matches, public.unmatch, public.delete_my_account, public.saath_platform_fee TO authenticated;
-- Everything else (saath_tick, compute_matches, review_verification, cancel_event_internal,
-- promote_waitlist, enqueue_notification, dating_ok, resolve_match_type) is server-only.
